mapper.select:
select count(*)
from tbl_staff
where staff_id = #{value}

mapper.insert:
insert into tbl_staff
(
    staff_id
    , staff_pw
    , staff_name
    , staff_gender
    , staff_birth
    , staff_phone
    , staff_mail
)
values
(
    #{staff_id}
    , #{staff_pw}
    , #{staff_name}
    , #{staff_gender}
    , #{staff_birth}
    , #{staff_phone}
    , #{staff_mail}
)

mapper.update:
update tbl_staff
set staff_state = 1
where staff_id = #{value}

update tbl_staff
set
	staff_name     = #{staff_name}
	, staff_no       = #{staff_no}
	, staff_gender   = #{staff_gender}
	, staff_birth    = #{staff_birth}
	, staff_part     = #{staff_part}
	, staff_position = #{staff_position}
	, staff_phone    = #{staff_phone}
	, staff_mail     = #{staff_mail}
	, staff_state    = #{staff_state}
where staff_id = #{staff_id}
